def luhn_valid(s):
    s = s.replace(" ", "")
    if len(s) < 2 or not s.isdigit() or not s.isascii():
        return False
    total = 0
    for i, c in enumerate(reversed(s)):
        d = int(c)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0
